import{_ as a,o as s,c as t,a3 as n}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Styliser les panneaux intégrés dans un frame (expérimental)","description":"Activer le style UIX dans les frames pris en charge des applications et des panneaux personnalisés.","frontmatter":{"title":"Styliser les panneaux intégrés dans un frame (expérimental)","description":"Activer le style UIX dans les frames pris en charge des applications et des panneaux personnalisés."},"headers":[],"relativePath":"fr/projects/uix/extras/style-frame-panels.md","filePath":"fr/projects/uix/extras/style-frame-panels.md","lastUpdated":1792857501000}'),i={name:"fr/projects/uix/extras/style-frame-panels.md"};function r(l,e,o,p,d,c){return s(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="styliser-les-panneaux-integres-dans-un-frame-experimental" tabindex="-1">Styliser les panneaux intégrés dans un frame (expérimental) <a class="header-anchor" href="#styliser-les-panneaux-integres-dans-un-frame-experimental" aria-label="Permalink to &quot;Styliser les panneaux intégrés dans un frame (expérimental)&quot;">​</a></h1><p>Par défaut, UIX n&#39;injecte pas de styles dans le contenu des frames. Activez ce réglage expérimental pour exécuter le moteur interne de UIX dans les frames de même origine des applications et des panneaux personnalisés pris en charge. Le style de l&#39;élément hôte avec <code>uix-app</code> et <code>uix-panel-custom</code> n&#39;est pas affecté par cette option.</p><div class="warning custom-block"><p class="custom-block-title">Compatibilité avec les frameworks</p><p>Le moteur des frames a été largement testé avec le frontend de Home Assistant basé sur Lit. Les applications et panneaux personnalisés intégrés dans une iframe et développés avec d&#39;autres frameworks peuvent avoir un cycle de vie ou un comportement DOM fantôme différent. Les panneaux dotés d&#39;une racine DOM légère classique et sans limites de DOM fantôme fonctionnent généralement bien. Ceux qui gèrent leur DOM de façon réactive ou utilisent un DOM fantôme complexe doivent être validés pour chaque application. Inspectez la frame, testez chaque sélecteur et signalez les problèmes de compatibilité.</p><p>Dans les frames qui n&#39;utilisent pas Lit, UIX applique une feuille de style de secours au lieu d&#39;insérer un <code>uix-node</code> dans le DOM de l&#39;application. Cette solution prend en charge le CSS direct, y compris les modèles, mais pas les chemins de sélecteurs YAML de UIX. Utilisez des sélecteurs CSS classiques dans le bloc de style direct.</p></div><h2 id="reglage-dans-l-interface-de-l-integration" tabindex="-1">Réglage dans l&#39;interface de l&#39;intégration <a class="header-anchor" href="#reglage-dans-l-interface-de-l-integration" aria-label="Permalink to &quot;Réglage dans l&#39;interface de l&#39;intégration&quot;">​</a></h2><p>Cette option est <strong>désactivée par défaut</strong>. Pour l&#39;activer :</p><ol><li>Dans Home Assistant, ouvrez <strong>Paramètres → Appareils et services → UI eXtension → Configurer</strong>.</li><li>Choisissez <strong>Réglages expérimentaux</strong> dans le menu.</li><li>Activez <strong>Styliser les panneaux intégrés dans un frame</strong>.</li><li>Enregistrez.</li></ol><p>Le réglage est immédiatement disponible dans toutes les sessions de navigateur connectées. Il peut être nécessaire de recharger la page pour l&#39;appliquer à un panneau déjà affiché.</p><h2 id="comportement-lorsque-l-option-est-activee" tabindex="-1">Comportement lorsque l&#39;option est activée <a class="header-anchor" href="#comportement-lorsque-l-option-est-activee" aria-label="Permalink to &quot;Comportement lorsque l&#39;option est activée&quot;">​</a></h2><p>Lorsque cette option est activée :</p><ul><li>UIX installe son moteur interne, indépendant du type de panneau, dans les frames de même origine prises en charge pour les applications et les panneaux personnalisés.</li><li>Pour les frames de panneaux personnalisés, le nom du panneau sert de cible de thème. Pour les applications, UIX essaie d&#39;abord le slug complet du module complémentaire, puis son slug indépendant du dépôt.</li><li>UIX n&#39;ajoute un nœud de style que si le thème actif définit une cible <code>uix-&lt;target&gt;</code> correspondante. Les frames sans section <code>uix-&lt;target&gt;</code> correspondante restent inchangées.</li><li>Si UIX détecte qu&#39;aucun thème n&#39;est appliqué, UIX Styling utilise le thème actuellement chargé dans le frontend de Home Assistant. Certains panneaux personnalisés, comme HACS, appliquent eux-mêmes le thème ; UIX Styling l&#39;hérite alors.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Le moyen le plus simple de trouver la cible <code>uix-&lt;target&gt;</code> consiste à consulter la console développeur du navigateur. L&#39;information de chargement UIX générée par <code>uixFrame.js</code> ressemble à ceci :</p><p><span style="background:#CE3226;color:white;padding:2px 5px;font-weight:bold;border-radius:5px;">💡 UIX 8.4.0 IS INSTALLED 💡 for hacs-frontend</span></p><p>La dernière partie du message indique la cible, ici <code>hacs-frontend</code>.</p></div>',11)])])}const g=a(i,[["render",r]]);export{m as __pageData,g as default};
